parameters.inputSchema:
={
  "type": "object",
  "properties": {
    "name": { 
      "type": "string", 
      "description": "Full name of the client found in message" 
    },
    "email": { 
      "type": "string", 
      "description": "Valid email address extracted directly from the user's input (e.g. name@domain.com)" 
    },
    "meeting_topic": { 
      "type": "string", 
      "description": "Topic, purpose, or reason for the meeting" 
    },
    "start_time": { 
      "type": "string", 
      "description": "Start date and time in ISO format (YYYY-MM-DDTHH:mm:ss)" 
    },
    "end_time": { 
      "type": "string", 
      "description": "End date and time in ISO format (YYYY-MM-DDTHH:mm:ss) calculated based on duration (default 60 mins)" 
    },
    "meeting_date": { 
      "type": "string", 
      "description": "Extract the meeting date in the format (YYYY-MM-DD)" 
    },
    "meeting_time": { 
      "type": "string", 
      "description": "Meeting start time in format (hh:mm tt)" 
    }
  },
  "required": ["name", "email", "meeting_topic","start_time", "end_time", "meeting_date", "meeting_time"]
}

parameters.text:
=✅ Your meeting has been booked successfully.

Date: {{ $('AI Agent').item.json.output.meeting_date }}


Time: {{ DateTime.fromFormat($('AI Agent').item.json.output.meeting_time, 'HH:mm:ss').toFormat('h:mm a') }}

Topic: AI Automation Discussion

See you soon!
